import json, os

stories = {
    "assets/alamat/pambansa/alamat_ng_pinya.json": {"id":"alamat_ng_pinya","region":"Pambansa","category":"likas","emoji":"🍍","title_fil":"Alamat ng Pinya","title_eng":"Legend of the Pineapple","chapters":[{"chapter":1,"title_fil":"Ang Batang Tamad","title_eng":"The Lazy Child","text_fil":"Noong unang panahon, may isang biyuda na may isang anak na babae. Siya ay napaka-tamad at hindi tumutulong sa kanyang ina kahit kailan. Tuwing hihingi ng tulong ang kanyang ina, palagi siyang may dahilan para hindi gumawa ng trabaho.","text_eng":"Long ago there was a widow with one daughter. She was very lazy and never helped her mother. Whenever her mother asked for help she always had an excuse not to work."},{"chapter":2,"title_fil":"Ang Sumpa ng Ina","title_eng":"The Mothers Curse","text_fil":"Isang araw nagkasakit ang ina at hiniling sa anak na tumulong ngunit tumanggi ang bata. Lumuha ang ina at sinabi sana magkaroon ka ng maraming mata. Kinabukasan naging pinya na ang anak na puno ng mga mata sa buong katawan.","text_eng":"One day the mother got sick and asked her child for help but the child refused. The mother cried and said I wish you had many eyes. The next morning the child became a pineapple covered with eyes all over its body."}]},
    "assets/alamat/pambansa/si_bathala.json": {"id":"si_bathala","region":"Pambansa","category":"diyos","emoji":"⚡","title_fil":"Si Bathala at ang Paglikha","title_eng":"Bathala and the Creation","chapters":[{"chapter":1,"title_fil":"Ang Pinakamataas na Diyos","title_eng":"The Supreme God","text_fil":"Sa simula pa ng lahat si Bathala na ang nandoon. Siya ang Maykapal na lumikha ng lahat ng bagay. Naninirahan siya sa kaitaasan ng langit sa lugar na tinatawag na Kaluwalhatian.","text_eng":"From the very beginning Bathala already existed. He was the Creator the maker of all things. He lived in the highest heaven in a place called Kaluwalhatian."},{"chapter":2,"title_fil":"Ang Paglikha ng Tao","title_eng":"The Creation of Man","text_fil":"Kinuha ni Bathala ang lupa mula sa lupa ang hininga mula sa hangin at ang init mula sa araw. Hinalo niya ang lahat at ginawa ang unang tao. Hiningahan niya ito ng kanyang espiritu at nabuhay ang tao.","text_eng":"Bathala took earth from the ground breath from the wind and warmth from the sun. He mixed them all and made the first person. He breathed his spirit into it and the person came to life."}]},
    "assets/alamat/pambansa/alamat_ng_sampaguita.json": {"id":"alamat_ng_sampaguita","region":"Pambansa","category":"likas","emoji":"🌸","title_fil":"Alamat ng Sampaguita","title_eng":"Legend of the Sampaguita","chapters":[{"chapter":1,"title_fil":"Ang Dalawang Magkasintahan","title_eng":"The Two Lovers","text_fil":"Noong sinaunang panahon may dalawang magkasintahang lubos na nagmamahal sa isa't isa. Ang lalaki ay isang matapang na mandirigma at ang babae ay isang magandang dalaga na kilala ng buong nayon.","text_eng":"In ancient times there were two lovers who deeply loved each other. The man was a brave warrior and the woman was a beautiful maiden known throughout the village."},{"chapter":2,"title_fil":"Ang Pangako","title_eng":"The Promise","text_fil":"Hindi na bumalik ang mandirigma mula sa digmaan. Araw-araw pumupunta ang dalaga sa lugar kung saan sila nagkita at binibitiwan ang salitang sumampalataya ako. Isang umaga lumitaw ang maputing bulaklak na sampaguita sa lugar na iyon bilang simbolo ng kanyang katapatan.","text_eng":"The warrior never returned from war. Every day the maiden went to the place where they last met and whispered I promise you faithfulness. One morning white sampaguita flowers appeared there as a symbol of her loyalty."}]},
    "assets/alamat/pambansa/ang_tikbalang.json": {"id":"ang_tikbalang","region":"Pambansa","category":"nilalang","emoji":"🐴","title_fil":"Ang Tikbalang","title_eng":"The Tikbalang","chapters":[{"chapter":1,"title_fil":"Ang Nilalang ng Kagubatan","title_eng":"The Forest Creature","text_fil":"Sa malalim na kagubatan ng Pilipinas naninirahan ang isang kakaibang nilalang na tinatawag na Tikbalang. Siya ay kalahating tao at kalahating kabayo na napakalaki at ang kanyang mga mata ay kumikinang sa dilim tulad ng apoy.","text_eng":"In the deep forests of the Philippines lives a strange creature called the Tikbalang. It is half human and half horse very large and its eyes shine in the darkness like fire."},{"chapter":2,"title_fil":"Paano Mapipigilan ang Tikbalang","title_eng":"How to Stop the Tikbalang","text_fil":"Kapag naliligaw ka sa kagubatan dahil sa Tikbalang baligtarin ang iyong damit at huwag matakot. Kapag ginanito mawawala ang kanyang kapangyarihan at mahahanap mo ang tamang daan pauwi.","text_eng":"When you get lost in the forest because of the Tikbalang turn your clothes inside out and do not be afraid. When you do this its power disappears and you will find the right path home."}]},
    "assets/alamat/luzon/daragang_magayon.json": {"id":"daragang_magayon","region":"Albay, Bicol","category":"likas","emoji":"🌋","title_fil":"Alamat ng Daragang Magayon","title_eng":"Legend of the Beautiful Maiden","chapters":[{"chapter":1,"title_fil":"Ang Pinakamagandang Dalaga","title_eng":"The Most Beautiful Maiden","text_fil":"Sa lupain ng Bicol sa paanan ng isang malaking bundok may nayon na tinatahanan ng isang datu. Ang anak niyang babae ay tinatawag ng lahat na Daragang Magayon at ang kanyang kagandahan ay walang kapantay sa buong lupain.","text_eng":"In the land of Bicol at the foot of a great mountain there was a village ruled by a chieftain. His daughter was called Daragang Magayon and her beauty was unmatched throughout the entire land."},{"chapter":2,"title_fil":"Ang Trahedya at ang Bundok","title_eng":"The Tragedy and the Mountain","text_fil":"Sa gitna ng labanan para iligtas ang kanyang ama isang palaso ang tumama kay Daragang Magayon. Habang namamatay siya hinahawakan ni Panganoron ang kanyang kamay. Inilibing sila nang magkasama at sa lugar na iyon tumaas ang lupa at naging ang Bulkang Mayon na may perpektong hugis bilang alaala ng kanyang kagandahan.","text_eng":"In the middle of a battle to save her father an arrow struck Daragang Magayon. As she was dying Panganoron held her hand. They were buried together and in that place the earth rose to become Mayon Volcano with its perfect shape as a memory of her beauty."}]},
    "assets/alamat/luzon/si_lam_ang.json": {"id":"si_lam_ang","region":"Ilocos","category":"bayani","emoji":"⚔️","title_fil":"Si Lam-ang Bayani ng Ilocos","title_eng":"Lam-ang Hero of Ilocos","chapters":[{"chapter":1,"title_fil":"Ang Kahanga-hangang Kapanganakan","title_eng":"The Miraculous Birth","text_fil":"Nang ipanganak si Lam-ang kaagad siyang nagsalita at nagpili ng kanyang sariling pangalan. Ako ay Lam-ang kanyang sinabi at nagulat ang lahat dahil nagsasalita ang sanggol. Ito ang simula ng buhay ng pinakadakilang bayani ng Ilocos.","text_eng":"When Lam-ang was born he immediately spoke and chose his own name. I am Lam-ang he said and everyone was shocked because the baby was speaking. This was the beginning of the life of the greatest hero of Ilocos."},{"chapter":2,"title_fil":"Si Ines Kannoyan","title_eng":"Ines Kannoyan","text_fil":"Nang dumating si Lam-ang sa bahay ni Ines ipinatugtog ng kanyang tandang ang mahiwagang awit at natumba ang bahay sa lakas ng tunog. Natawa si Ines at napahanga sa kanyang tapang at doon nagsimula ang kanilang pagmamahal na pumalit sa lahat ng mga karibal.","text_eng":"When Lam-ang arrived at the house of Ines his rooster crowed its magical song and the house collapsed from the sound. Ines laughed and was impressed by his bravery and there their love began replacing all his rivals."}]},
    "assets/alamat/luzon/alamat_ng_baguio.json": {"id":"alamat_ng_baguio","region":"Benguet, Luzon","category":"likas","emoji":"🌲","title_fil":"Alamat ng Lungsod ng Baguio","title_eng":"Legend of Baguio City","chapters":[{"chapter":1,"title_fil":"Ang Lupain ng Igorot","title_eng":"Land of the Igorot","text_fil":"Sa mataas na kabundukan ng Cordillera naninirahan ang mga Igorot na may malalim na koneksyon sa lupa at kalikasan. Ang lugar na tinatawag nilang Kafagway ay isang malamig na kapatagan sa gitna ng mga bundok na puno ng pino at ulap na sagrado sa kanila.","text_eng":"In the high mountains of the Cordillera the Igorot people lived in deep connection with the earth and nature. The place they called Kafagway was a cool plateau among mountains full of pines and clouds sacred to them."}]},
    "assets/alamat/luzon/alamat_ng_taal.json": {"id":"alamat_ng_taal","region":"Batangas, Luzon","category":"likas","emoji":"🌊","title_fil":"Alamat ng Lawa ng Taal","title_eng":"Legend of Taal Lake","chapters":[{"chapter":1,"title_fil":"Ang Nayon na Nalunod","title_eng":"The Sunken Village","text_fil":"Noong unang panahon sa lugar kung saan naroon ngayon ang Lawa ng Taal may isang masayang nayon. Naging mayabang ang mga tao at isang gabi nagpadala ang mga diyos ng malaking baha. Ang buong nayon ay nalunod at naging lawa ang lugar at ang bulkan sa gitna ay ang galit ng mga espiritu.","text_eng":"Long ago where Taal Lake now lies there was a happy village. The people became arrogant and one night the gods sent a great flood. The entire village was submerged and became the lake and the volcano in the middle is the anger of the spirits."}]},
    "assets/alamat/visayas/lapu_lapu.json": {"id":"lapu_lapu","region":"Cebu, Visayas","category":"bayani","emoji":"🛡️","title_fil":"Si Lapu-Lapu Ang Unang Bayani","title_eng":"Lapu-Lapu The First Hero","chapters":[{"chapter":1,"title_fil":"Ang Datu ng Mactan","title_eng":"The Chieftain of Mactan","text_fil":"Si Lapu-Lapu ay ang datu ng isla ng Mactan sa Cebu. Nang dumating ang mga Espanyol maraming datu ang sumuko ngunit si Lapu-Lapu ay tumayo nang matapang at sinabi hindi kami magpapasakop sa mga dayuhan at handa kaming ipaglaban ang aming kalayaan.","text_eng":"Lapu-Lapu was the chieftain of the island of Mactan in Cebu. When the Spaniards arrived many chieftains surrendered but Lapu-Lapu bravely stood and said we will not submit to foreigners and we are ready to fight for our freedom."},{"chapter":2,"title_fil":"Ang Tagumpay sa Mactan","title_eng":"The Victory at Mactan","text_fil":"Noong Abril dalawamput pito ng taong isang libo limang daan at dalawampu't isa nilabanan ni Lapu-Lapu at ng kanyang mga mandirigma ang mga Espanyol. Kahit outnumbered hindi sila umatras at sa gitna ng labanan napatay si Magellan. Ang tagumpay na ito ay naging simbolo ng kalayaan ng bawat Pilipino.","text_eng":"On April twenty seventh fifteen twenty one Lapu-Lapu and his warriors fought the Spaniards. Even though outnumbered they did not retreat and in the battle Magellan was killed. This victory became a symbol of freedom for every Filipino."}]},
    "assets/alamat/visayas/chocolate_hills.json": {"id":"chocolate_hills","region":"Bohol, Visayas","category":"likas","emoji":"⛰️","title_fil":"Alamat ng Chocolate Hills","title_eng":"Legend of the Chocolate Hills","chapters":[{"chapter":1,"title_fil":"Ang Luha ng Higante","title_eng":"The Giants Tears","text_fil":"Sa lupain ng Bohol may isang higanteng nagngangalang Arogo na umibig nang buong puso sa isang mortal na babae na si Aloya. Nang mamatay si Aloya umiyak si Arogo nang walang tigil at ang kanyang malalaking luha ay nahulog sa lupa ng Bohol at naging daan-daang bilugang burol na kapag tag-araw ay nagiging kayumanggi tulad ng tsokolate.","text_eng":"In the land of Bohol there was a giant named Arogo who fell deeply in love with a mortal woman named Aloya. When Aloya died Arogo cried endlessly and his giant tears fell on the ground of Bohol becoming hundreds of rounded hills that turn brown like chocolate during summer."}]},
    "assets/alamat/visayas/bantay_araw.json": {"id":"bantay_araw","region":"Iloilo, Visayas","category":"diyos","emoji":"☀️","title_fil":"Si Bantay Araw","title_eng":"The Sun Guardian","chapters":[{"chapter":1,"title_fil":"Ang Tagapangalaga ng Araw","title_eng":"The Guardian of the Sun","text_fil":"Sa sinaunang paniniwala ng mga Visayano may isang diyos na nagbabantay sa araw na tinatawag na Bantay Araw. Siya ang nagdadala ng liwanag sa umaga at nagtatago ng araw sa gabi. Kapag mapula ang paglubog ng araw nagagalit si Bantay Araw at kailangan mag-ingat ang lahat bukas.","text_eng":"In ancient Visayan belief a god watched over the sun called Bantay Araw the Sun Guardian. He brought light each morning and hid the sun at night. When the sunset is red Bantay Araw is angry and everyone must be careful tomorrow."}]},
    "assets/alamat/mindanao/mount_apo.json": {"id":"mount_apo","region":"Davao, Mindanao","category":"likas","emoji":"🏔️","title_fil":"Alamat ng Bundok Apo","title_eng":"Legend of Mount Apo","chapters":[{"chapter":1,"title_fil":"Ang Hari ng mga Bundok","title_eng":"The King of Mountains","text_fil":"Ang Bundok Apo ay ang pinakamataas na bundok sa Pilipinas na may taas na dalawang libo siyam na raan at limampung apat na metro. Para sa mga katutubo ng Mindanao ito ay tahanan ng makapangyarihang diyos na si Apo Sandawa na tagapangalaga ng lahat ng nilalang sa bundok.","text_eng":"Mount Apo is the highest mountain in the Philippines standing two thousand nine hundred fifty four meters tall. For the indigenous peoples of Mindanao it is the home of the powerful god Apo Sandawa who guards all creatures on the mountain."}]},
    "assets/alamat/mindanao/si_diwata.json": {"id":"si_diwata","region":"Mindanao","category":"nilalang","emoji":"🧚","title_fil":"Ang Diwata ng Kagubatan","title_eng":"The Forest Fairy","chapters":[{"chapter":1,"title_fil":"Ang Tagapangalaga ng Kagubatan","title_eng":"The Forest Guardian","text_fil":"Sa malalim na kagubatan ng Mindanao naninirahan ang mga Diwata na mga espiritung may magandang anyo at makapangyarihang kakayahan. Sila ang tagapangalaga ng mga puno ilog at mga hayop at kapag ginalang ng mga tao ang kalikasan pinagpapala sila ng mga Diwata ng masaganang buhay.","text_eng":"In the deep forests of Mindanao live the Diwata, spirits with beautiful forms and powerful abilities. They guard the trees rivers and animals and when people respect nature the Diwata bless them with an abundant life."}]},
    "assets/alamat/mindanao/si_rajah_muda.json": {"id":"si_rajah_muda","region":"Lanao, Mindanao","category":"bayani","emoji":"👑","title_fil":"Si Rajah Muda at ang Lawa ng Lanao","title_eng":"Rajah Muda and Lake Lanao","chapters":[{"chapter":1,"title_fil":"Ang Paglikha ng Lawa","title_eng":"The Creation of the Lake","text_fil":"Isang taon nagkaroon ng matinding tagtuyot at nagutom ang mga tao sa lupain ng Maranao. Nanalangin si Rajah Muda sa kanyang mga ninuno at sinabihan siyang kailangan niyang ialay ang kanyang sariling lupain. Nang sumang-ayon siya biglang lumitaw ang malaking lawa ng Lanao na nagbigay-buhay at pag-asa sa kanyang bayan.","text_eng":"One year a severe drought struck and the people of the Maranao land starved. Rajah Muda prayed to his ancestors and was told he needed to sacrifice his own land. When he agreed the great Lake Lanao suddenly appeared bringing life and hope to his kingdom."}]},
    "assets/alamat/palawan/underground_river.json": {"id":"underground_river","region":"Palawan","category":"likas","emoji":"🌊","title_fil":"Alamat ng Underground River","title_eng":"Legend of the Underground River","chapters":[{"chapter":1,"title_fil":"Ang Mundo sa Ilalim ng Lupa","title_eng":"The World Beneath the Earth","text_fil":"Sa kanlurang bahagi ng Palawan may isang misteryosong ilog na dumadaloy sa ilalim ng mga bundok at malalim na yungib. Para sa mga Tagbanua ito ay isang sagradong lugar na puno ng mga espiritu ng kanilang mga ninuno na nagbabantay sa bawat bato at agos ng tubig.","text_eng":"In western Palawan a mysterious river flows beneath the mountains and deep caves. For the Tagbanua people it is a sacred place full of the spirits of their ancestors who watch over every rock and flow of water."},{"chapter":2,"title_fil":"Ang Pitong Langit","title_eng":"The Seven Heavens","text_fil":"Sinasabi ng mga Tagbanua na ang ilog ay nagdadala sa pitong langit ang pinakamataas na antas ng espirituwal na mundo. Ang mga kaluluwa ng mga namatay ay dumadaan sa ilog na ito patungo sa kanilang huling pahingahan kaya ang underground river ay isang sagradong tulay sa pagitan ng buhay at kamatayan.","text_eng":"The Tagbanua say the river leads to the seven heavens the highest spiritual realm. The souls of the departed pass through this river on their way to their final resting place making the underground river a sacred bridge between life and death."}]},
    "assets/alamat/palawan/el_nido.json": {"id":"el_nido","region":"Palawan","category":"likas","emoji":"🏝️","title_fil":"Alamat ng El Nido","title_eng":"Legend of El Nido","chapters":[{"chapter":1,"title_fil":"Ang Pugad ng mga Ibon","title_eng":"The Birds Nest","text_fil":"Ang El Nido ay nagmula sa salitang pugad sa wikang Espanyol at ang pangalan ay nanggaling sa mga pugad ng mga balinsasayaw na itinayo sa matarik na mga bato sa dalampasigan ng Palawan na ginagamit sa paggawa ng bird's nest soup na isang mahal na pagkain.","text_eng":"El Nido comes from the Spanish word for nest and the name came from the nests of swiftlets built on the steep cliffs along the shores of Palawan which are used to make bird nest soup a very expensive delicacy."}]},
    "assets/alamat/palawan/si_manuyog.json": {"id":"si_manuyog","region":"Palawan","category":"nilalang","emoji":"🐊","title_fil":"Si Manuyog at ang Buwaya","title_eng":"Manuyog and the Crocodile","chapters":[{"chapter":1,"title_fil":"Ang Kasunduan ng Tao at Buwaya","title_eng":"The Agreement Between Man and Crocodile","text_fil":"Sa mga ilog ng Palawan may isang espiritu na nagbabago ng anyo minsan tao minsan buwaya na tinatawag na Manuyog. Siya ang tagapangalaga ng ilog at gumawa ng kasunduan sa pagitan ng mga tao at mga buwaya na hindi sila mag-aatake sa isa't isa habang sinusunod ang kasunduan.","text_eng":"In the rivers of Palawan lives a shape-shifting spirit sometimes human sometimes crocodile called Manuyog. He is the guardian of the river and made an agreement between the people and the crocodiles that they would not attack each other as long as the agreement is honored."}]}
}

for path, content in stories.items():
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(content, f, ensure_ascii=False, indent=2)
    print(f"OK: {path}")

print("\nDONE!")
